 12		"strings"
 13	)
 14	
 15	type chatHistoryMessage struct {
 16		Type      string `json:"type"`
 17		Content   any    `json:"content"`
 18		ToolCalls []struct {
 19			ID        string `json:"id"`
 20			Name      string `json:"name"`
 21			Arguments string `json:"arguments"`
 22		} `json:"tool_calls"`
 23		// PromptIndex is set by Grok only on genuine user prompts. Synthetic user
 24		// messages (system reminders, injected context) never carry it, so its
 25		// presence is the reliable signal for "the human typed this".
 26		PromptIndex *int `json:"prompt_index"`
 27		// SyntheticReason is set on Grok-injected user messages, e.g. "system_reminder".
 28		SyntheticReason string `json:"synthetic_reason"`
 29		// ToolCallID links a tool_result line back to the tool_use that produced it.
 30		ToolCallID string `json:"tool_call_id"`
 31		// Summary carries the human-readable reasoning summary on reasoning lines.
 32		Summary any `json:"summary"`
 33		// ModelID is stamped on assistant and reasoning lines.
 34		ModelID string `json:"model_id"`
 35	}
 36	
 37	// lastModelID returns the most recent model stamped on the transcript. Grok
 38	// rejects a restored session whose summary.json has no current_model_id.
 39	func lastModelID(messages []chatHistoryMessage) string {
 40		for i := len(messages) - 1; i >= 0; i-- {
 41			if id := strings.TrimSpace(messages[i].ModelID); id != "" {
 42				return id
 43			}
 44		}
 45		return ""
 46	}
 47	
 48	var userQueryPattern = regexp.MustCompile(`(?s)<user_query>\s*(.*?)\s*</user_query>`)
 49	
 50	func readChatHistoryMessages(path string) ([]chatHistoryMessage, error) {
 51		f, err := os.Open(path)
 52		if err != nil {
 53			return nil, err
 54		}
 55		defer func() { _ = f.Close() }()
 56	
 57		messages, err := scanChatHistory(f)
 58		if err != nil {
 59			return nil, err
 60		}
 61		return messages, nil
 62	}
 63	
 64	// scanChatHistory parses a chat_history.jsonl stream leniently.
 65	//
 66	// Entire scopes a checkpoint by slicing the transcript from a mid-session
 67	// offset, which can cut the first line in half, and it reads the file while
 68	// Grok is still appending to it, which can leave a half-flushed final line.
 69	// Neither case is corruption, so an unparseable line is skipped rather than
 70	// failing the whole parse. Erroring here surfaces to the user as the summary
 71	// falling back to raw bytes and reporting "no content to summarize".
 72	func scanChatHistory(r io.Reader) ([]chatHistoryMessage, error) {
 73		var messages []chatHistoryMessage
 74		scanner := bufio.NewScanner(r)
 75		scanner.Buffer(make([]byte, 0, 64*1024), 10*1024*1024)
 76		for scanner.Scan() {
 77			line := strings.TrimSpace(scanner.Text())
 78			if line == "" {
 79				continue
 80			}
 81			var message chatHistoryMessage
 82			if err := json.Unmarshal([]byte(line), &message); err != nil {
 83				continue
 84			}
 85			messages = append(messages, message)
 86		}
 87		return messages, scanner.Err()
 88	}
 89	
 90	func promptsFromChatHistory(messages []chatHistoryMessage, offset int) []string {
 91		if offset < 0 {
 92			offset = 0
 93		}
 94		if offset > len(messages) {
 95			offset = len(messages)
 96		}
 97		// Judge prompt_index over the whole transcript, not the scoped slice. A slice
 98		// that happens to contain no genuine prompt would otherwise look like a Grok
 99		// build that does not emit the tag and fall back to the loose heuristic,
100		// letting injected context through as user prompts.
101		marked := hasPromptIndex(messages)
102		var prompts []string
103		for _, message := range messages[offset:] {
104			if !isPromptCandidate(message, marked) {
105				continue
106			}
107			for _, text := range messageTextParts(message.Content) {
108				if prompt := extractUserQuery(text); prompt != "" {
109					prompts = append(prompts, prompt)
110				}
111			}
112		}
113		return prompts
114	}
115	
116	// hasPromptIndex reports whether Grok tagged any user line with prompt_index.
117	// Versions that emit the tag let us identify real prompts exactly; for any that
118	// do not, callers fall back to the <user_query> heuristic.
119	func hasPromptIndex(messages []chatHistoryMessage) bool {
120		for _, message := range messages {
121			if message.Type == roleUser && message.PromptIndex != nil {
122				return true
123			}
124		}
125		return false
126	}
127	
128	func isPromptCandidate(message chatHistoryMessage, marked bool) bool {
129		if message.Type != roleUser || message.SyntheticReason != "" {
130			return false
131		}
132		if marked {
133			return message.PromptIndex != nil
134		}
135		return true
136	}
137	
138	func summaryFromChatHistory(messages []chatHistoryMessage) (string, bool) {
139		for i := len(messages) - 1; i >= 0; i-- {
140			message := messages[i]
141			if message.Type != roleAssistant {
142				continue
143			}
144			if text, ok := assistantText(message); ok && strings.TrimSpace(text) != "" {
145				return strings.TrimSpace(text), true
146			}
147		}
148		return "", false
149	}
150	
151	func modifiedFilesFromChatHistory(messages []chatHistoryMessage, offset int) []string {
152		if offset < 0 {
153			offset = 0
154		}
155		if offset > len(messages) {
156			offset = len(messages)
157		}
158		seen := map[string]struct{}{}
159		for _, message := range messages[offset:] {
160			if message.Type != roleAssistant {
161				continue
162			}
163			for _, call := range message.ToolCalls {
164				if !isFileModificationTool(call.Name) {
165					continue
166				}
167				for _, path := range pathsFromToolArguments(call.Name, call.Arguments) {
168					if path = strings.TrimSpace(path); path != "" {
169						seen[path] = struct{}{}
170					}
171				}
172			}
173		}
174		files := make([]string, 0, len(seen))
175		for file := range seen {
176			files = append(files, file)
177		}
178		sort.Strings(files)
179		return files
180	}
181	
182	func messageTextParts(content any) []string {
183		switch value := content.(type) {
184		case string:
185			if strings.TrimSpace(value) == "" {
186				return nil
187			}
188			return []string{value}
189		case []any:
190			var parts []string
191			for _, item := range value {
192				if block, ok := item.(map[string]any); ok {
193					if text, ok := block["text"].(string); ok && strings.TrimSpace(text) != "" {
194						parts = append(parts, text)
195					}
196				}
197			}
198			return parts
199		default:
200			return nil
201		}
202	}
203	
204	// unwrapUserQuery strips the <user_query> wrapper Grok puts around the prompt it
205	// hands to UserPromptSubmit hooks. Passing it through verbatim leaves the markup
206	// in checkpoint titles, and renders the checkpoint Intent as literally
207	// "<user_query>". Text without the wrapper is returned trimmed.
208	func unwrapUserQuery(text string) string {
209		if match := userQueryPattern.FindStringSubmatch(text); len(match) > 1 {
210			return strings.TrimSpace(match[1])
211		}
212		return strings.TrimSpace(text)
213	}
214	
215	func extractUserQuery(text string) string {
216		if match := userQueryPattern.FindStringSubmatch(text); len(match) > 1 {
217			return strings.TrimSpace(match[1])
218		}
219		// Grok injects context into the user role wrapped in a tag of its own
220		// (<user_info>, <rules>, <system-reminder>, ...). Without prompt_index to go
221		// on, treat any such wrapper as injected rather than matching a fixed list,
222		// which only ever covered the wrappers that had been observed.
223		trimmed := strings.TrimSpace(text)
224		if trimmed == "" || isWrappedContext(trimmed) {
225			return ""
226		}
227		return trimmed
228	}
229	
230	// isWrappedContext reports whether text opens with an XML-ish wrapper tag, the
231	// shape Grok uses for context it injects into the user role. Only consulted on
232	// the fallback path, where no prompt_index is available to be exact.
233	func isWrappedContext(text string) bool {
234		if !strings.HasPrefix(text, "<") {
235			return false
236		}
237		end := strings.IndexAny(text, " \t\n>")
238		if end <= 1 || text[end] != '>' {
239			return false
240		}
241		return !strings.EqualFold(text[1:end], "user_query")
242	}
243	
244	func assistantText(message chatHistoryMessage) (string, bool) {
245		switch value := message.Content.(type) {
246		case string:
247			return strings.TrimSpace(value), value != ""
248		default:
249			parts := messageTextParts(message.Content)
250			if len(parts) == 0 {
251				return "", false
252			}
253			return strings.TrimSpace(parts[0]), true
254		}
255	}
