182	func messageTextParts(content any) []string {
183		switch value := content.(type) {
184		case string:
185			if strings.TrimSpace(value) == "" {
186				return nil
187			}
188			return []string{value}
189		case []any:
190			var parts []string
191			for _, item := range value {
