274	// compactChatHistoryBytes condenses a Grok chat_history.jsonl, the only
275	// transcript format this adapter produces or consumes. It reads the bytes it is
276	// given and never inspects a file name, so a slice Entire has scoped or copied
277	// elsewhere compacts exactly like the file in Grok's session directory.
278	func compactChatHistoryBytes(data []byte) ([]byte, error) {
279		messages, err := readChatHistoryMessagesFromBytes(data)
280		if err != nil {
281			return nil, err
282		}
283		marked := hasPromptIndex(messages)
284		results := toolResultsByCallID(messages)
285		consumed := make(map[string]bool, len(results))
286		var buf bytes.Buffer
287		for _, message := range messages {
288			switch message.Type {
289			case "tool_result":
290				// A checkpoint slice can start after the assistant line that issued
291				// the call, orphaning its result. Emit it standalone so the tool
292				// output still reaches the summarizer.
293				result, ok := results[message.ToolCallID]
294				if !ok || consumed[message.ToolCallID] {
295					continue
296				}
297				consumed[message.ToolCallID] = true
298				if err := writeCompactLine(&buf, compactLine{
299					V: 1, Agent: AgentName, CLIVersion: compactCLIVersion, Type: roleAssistant,
300					ID: message.ToolCallID,
301					Content: []any{compactToolUseBlock{
302						Type: "tool_use", ID: message.ToolCallID, Name: "unknown", Result: result,
303					}},
304				}); err != nil {
305					return nil, err
306				}
307			case roleUser:
308				if !isPromptCandidate(message, marked) {
309					continue
310				}
311				for _, text := range messageTextParts(message.Content) {
312					if prompt := extractUserQuery(text); prompt != "" {
313						if err := writeCompactLine(&buf, compactLine{
314							V: 1, Agent: AgentName, CLIVersion: compactCLIVersion, Type: roleUser,
315							Content: []compactUserTextBlock{{Text: prompt}},
316						}); err != nil {
317							return nil, err
318						}
319					}
320				}
321			case "reasoning":
322				// Keep the plaintext reasoning summary. encrypted_content is
323				// deliberately dropped: it is opaque to a summarizer and is the
324				// field redaction mangles.
325				text := reasoningSummaryText(message.Summary)
326				if text == "" {
327					continue
328				}
329				if err := writeCompactLine(&buf, compactLine{
330					V: 1, Agent: AgentName, CLIVersion: compactCLIVersion, Type: roleAssistant,
331					Content: []compactAssistantTextBlock{{Type: "thinking", Text: text}},
332				}); err != nil {
333					return nil, err
334				}
335			case roleAssistant:
336				for _, call := range message.ToolCalls {
337					block := compactToolUseBlock{
338						Type: "tool_use", ID: call.ID, Name: call.Name,
339						Input: decodeRawObject(json.RawMessage(call.Arguments)),
340					}
341					if result, ok := results[call.ID]; ok {
342						block.Result = result
343						consumed[call.ID] = true
344					}
345					if err := writeCompactLine(&buf, compactLine{
346						V: 1, Agent: AgentName, CLIVersion: compactCLIVersion, Type: roleAssistant,
347						ID: call.ID, Content: []any{block},
348					}); err != nil {
349						return nil, err
350					}
351				}
352				if text, ok := assistantText(message); ok && text != "" {
353					if err := writeCompactLine(&buf, compactLine{
354						V: 1, Agent: AgentName, CLIVersion: compactCLIVersion, Type: roleAssistant,
355						Content: []compactAssistantTextBlock{{Type: "text", Text: text}},
356					}); err != nil {
357						return nil, err
358					}
359				}
360			}
361		}
362		if buf.Len() == 0 {
363			return nil, errors.New("compact transcript produced no output")
364		}
365		return buf.Bytes(), nil
366	}
