372	// toolResultsByCallID indexes tool_result lines so each tool_use block can carry
373	// its output. Grok writes results as separate lines keyed by tool_call_id; without
374	// this the compacted transcript shows every call with no result.
375	func toolResultsByCallID(messages []chatHistoryMessage) map[string]*compactToolResult {
376		results := make(map[string]*compactToolResult)
377		for _, message := range messages {
378			if message.Type != "tool_result" || message.ToolCallID == "" {
379				continue
380			}
381			parts := messageTextParts(message.Content)
382			if len(parts) == 0 {
383				if text, ok := message.Content.(string); ok && strings.TrimSpace(text) != "" {
384					parts = []string{text}
385				}
386			}
387			results[message.ToolCallID] = &compactToolResult{
388				Output: strings.Join(parts, "\n"),
389				Status: "success",
390			}
391		}
392		return results
393	}
394	
395	// reasoningSummaryText pulls plain text out of a reasoning line's summary, which
396	// Grok writes as a list of {type: summary_text, text: ...} blocks.
397	func reasoningSummaryText(summary any) string {
398		switch value := summary.(type) {
399		case string:
400			return strings.TrimSpace(value)
401		case []any:
402			var parts []string
403			for _, item := range value {
404				block, ok := item.(map[string]any)
405				if !ok {
406					continue
407				}
408				if text, ok := block["text"].(string); ok && strings.TrimSpace(text) != "" {
409					parts = append(parts, strings.TrimSpace(text))
410				}
411			}
412			return strings.Join(parts, "\n")
413		default:
414			return ""
415		}
416	}
