418	// sanitizeTranscriptForStorage removes Grok's opaque reasoning payloads from a
419	// copy of the transcript before Entire stores it.
420	//
421	// Grok stamps each reasoning line with an "encrypted_content" blob of
422	// high-entropy base64. Two reasons not to store it. It is big: a
423	// reasoning-heavy session produced values up to 12 KB, 15% of the transcript,
424	// and Entire re-stores the transcript on every checkpoint. And its name does not
425	// match the "*signature" rule in the CLI redactor, so the entropy scanner
426	// rewrites it to REDACTED, which makes the session unreplayable ("This session's
427	// conversation history is incompatible with the current model"). Grok replays
428	// fine when the field is absent, so dropping it beats trying to preserve it.
429	//
430	// This mirrors the built-in Codex agent's SanitizeTranscriptForStorage. The
431	// external agent protocol exposes no sanitizer hook, so it runs in the adapter's
432	// read paths instead. Grok's own chat_history.jsonl is never modified here.
433	func sanitizeTranscriptForStorage(data []byte) []byte {
434		// A transcript without the marker cannot change, so skip parsing entirely.
435		if !bytes.Contains(data, []byte(encryptedContentKey)) {
436			return data
437		}
438	
439		// Split rather than scan: this preserves whether the transcript ended with a
440		// newline. Appending one to a half-flushed final line would present a partial
441		// record as a complete one.
442		lines := bytes.Split(data, []byte("\n"))
443		for i, line := range lines {
444			lines[i] = sanitizeTranscriptLine(line)
445		}
446		return bytes.Join(lines, []byte("\n"))
447	}
448	
449	// sanitizeTranscriptLine strips encryptedContentKey from a single reasoning line,
450	// returning the line unchanged in every other case.
451	//
452	// Callers rely on one output line per input line. Entire counts checkpoint
453	// offsets in messages (see chatHistoryPosition), so dropping a line would shift
454	// every offset after it. An unparseable line is therefore kept verbatim rather
455	// than discarded: a scoped checkpoint slice can begin mid-line.
456	func sanitizeTranscriptLine(line []byte) []byte {
457		trimmed := bytes.TrimSpace(line)
458		if len(trimmed) == 0 || !bytes.Contains(trimmed, []byte(encryptedContentKey)) {
459			return line
460		}
461		// Decode into raw values, not map[string]any: every other field is re-encoded
462		// verbatim, so key order is kept and no integer is round-tripped through a
463		// float64. The result is written back into Grok's own transcript on restore.
464		var message map[string]json.RawMessage
465		if err := json.Unmarshal(trimmed, &message); err != nil {
466			return line
467		}
468		var messageType string
469		if err := json.Unmarshal(message[roleTypeKey], &messageType); err != nil || messageType != roleReasoning {
470			return line
471		}
472		if _, ok := message[encryptedContentKey]; !ok {
473			return line
474		}
475		delete(message, encryptedContentKey)
476		encoded, err := json.Marshal(message)
477		if err != nil {
478			return line
479		}
480		return encoded
481	}

