 83			return errMissingSessionRef
 84		}
 85		// Never truncate a real transcript with an empty snapshot. ReadSession
 86		// yields nil NativeData when the native transcript is missing, so an empty
 87		// payload means "nothing was captured", not "the session is empty" — and
 88		// writing it would destroy Grok's own history, which redaction cannot undo.
 89		if len(bytes.TrimSpace(session.NativeData)) == 0 {
 90			return errEmptySessionData
