102	// writeSessionSummary synthesizes the summary.json that Grok requires to
103	// recognize a session directory.
104	//
105	// Restoring chat_history.jsonl alone is not enough: Grok's session lookup
106	// ignores a directory with no summary.json, reports "Session not found
107	// locally", and falls back to the remote registry (404 for a local-only
108	// session). Worse, `grok --continue` then silently resumes a different, older
109	// session instead of failing, so a bad restore looks like a good one.
110	//
111	// An existing summary.json is left alone so a restore over a live session
112	// does not clobber Grok's own metadata.
113	func writeSessionSummary(sessionDir string, session protocol.AgentSessionJSON) error {
114		path := filepath.Join(sessionDir, "summary.json")
115		if _, err := os.Stat(path); err == nil {
116			return nil
117		} else if !errors.Is(err, os.ErrNotExist) {
118			return err
119		}
