121		sessionID := strings.TrimSpace(session.SessionID)
122		if sessionID == "" {
123			sessionID = filepath.Base(sessionDir)
124		}
125		// Canonicalize the way the session group name is canonicalized, or the two
126		// disagree wherever the repo path runs through a symlink (macOS /var).
127		cwd := resolveRepoPath(session.RepoPath)
128		timestamp := normalizedSummaryTime(session.StartTime)
129		count := countTranscriptLines(session.NativeData)
130	
131		messages, _ := readChatHistoryMessagesFromBytes(session.NativeData)
132		summary := grokSessionSummary{
133			Info:              grokSessionSummaryInfo{ID: sessionID, CWD: cwd},
134			SessionSummary:    restoredSummaryTitle,
135			GeneratedTitle:    restoredSummaryTitle,
136			CurrentModelID:    lastModelID(messages),
137			CreatedAt:         timestamp,
138			UpdatedAt:         timestamp,
139			LastActiveAt:      timestamp,
140			NumMessages:       count,
141			NumChatMessages:   count,
142			ChatFormatVersion: 1,
143			// Grok records git_root_dir with a trailing separator.
144			GitRootDir: strings.TrimSuffix(cwd, "/") + "/",
145			GrokHome:   grokHome(),
