154	// normalizedSummaryTime returns an RFC3339 timestamp Grok will accept.
155	//
156	// Entire sends an unset StartTime as a formatted zero time rather than an
157	// empty string, and Grok rejects a summary carrying a year-1 timestamp with
158	// "Session does not exist", so treat unparseable and zero values as absent.
159	func normalizedSummaryTime(value string) string {
160		parsed, err := time.Parse(time.RFC3339, strings.TrimSpace(value))
161		if err != nil || parsed.IsZero() || parsed.Year() < 2000 {
162			return time.Now().UTC().Format(time.RFC3339)
163		}
164		return parsed.UTC().Format(time.RFC3339)
165	}
