193		for start := 0; start < len(content); start += maxSize {
194			end := start + maxSize
195			if end > len(content) {
196				end = len(content)
197			}
198			chunk := make([]byte, end-start)
199			copy(chunk, content[start:end])
200			chunks = append(chunks, chunk)
201		}
202		return chunks, nil
203	}
