183	func parseHookInput(input []byte) (grokHookInputRaw, error) {
184		var raw grokHookInputRaw
185		input = bytes.TrimSpace(input)
186		if len(input) == 0 {
187			return raw, nil
188		}
189		if err := json.Unmarshal(input, &raw); err != nil {
190			return raw, fmt.Errorf("parse grok hook input: %w", err)
