195	func normalizeRawHook(raw *grokHookInputRaw, hookName string) {
196		if strings.TrimSpace(raw.SessionID) == "" {
197			raw.SessionID = strings.TrimSpace(raw.SessionIDCamel)
198		}
199		if strings.TrimSpace(raw.SessionID) == "" {
200			raw.SessionID = stubSessionID
201		}
202		if strings.TrimSpace(raw.Timestamp) == "" {
203			raw.Timestamp = time.Now().UTC().Format(time.RFC3339)
204		}
205		if strings.TrimSpace(raw.CWD) == "" {
206			raw.CWD = raw.WorkspaceRoot
207		}
208		if strings.TrimSpace(raw.Prompt) == "" {
209			raw.Prompt = raw.UserPrompt
210		}
211		if strings.TrimSpace(raw.Model) == "" && raw.LLMRequest.Model != "" {
212			raw.Model = raw.LLMRequest.Model
213		}
214		if len(bytes.TrimSpace(raw.ToolInput)) == 0 {
215			raw.ToolInput = firstRawMessage(raw.Inputs, raw.Input)
216		}
217		if len(bytes.TrimSpace(raw.ToolResponse)) == 0 {
218			raw.ToolResponse = firstRawMessage(raw.ToolResponse, raw.ToolResult, raw.Response)
219		}
220		if raw.ToolName == "" && (hookName == HookNamePostToolUse || hookName == HookNamePostToolUseFailure) {
221			raw.ToolName = "unknown"
222		}
223	}
