   459			return line
   460		}
   461		// Decode into raw values, not map[string]any: every other field is re-encoded
   462		// verbatim, so key order is kept and no integer is round-tripped through a
   463		// float64. The result is written back into Grok's own transcript on restore.
   464		var message map[string]json.RawMessage
   465		if err := json.Unmarshal(trimmed, &message); err != nil {
   466			return line
   467		}
