   114			HookNameSubagentStop:
   115			return nil, nil
   116		default:
   117			return nil, nil
   118		}
   119	}
   120	
   121	func (a *Agent) InstallHooks(_ bool, force bool) (int, error) {
   122		repoRoot := protocol.RepoRoot()
   123		path := hooksFilePath(repoRoot)
   124	
   125		rawHooks, err := readHookFile(path)
   126		if err != nil {
   127			return 0, err
   128		}
   129	
   130		if force {
   131			removeEntireHooks(rawHooks)
   132		}
   133	
   134		count := 0
   135		for _, spec := range hookSpecs {
   136			var matchers []grokHookMatcher
   137			parseHookType(rawHooks, spec.GrokEvent, &matchers)
   138			command := hookCommand(spec.HookName)
   139			var changed bool
   140			matchers, changed = upsertHook(matchers, spec.Matcher, spec.EntryName, command)
   141			if changed {
   142				count++
   143			}
   144			marshalHookType(rawHooks, spec.GrokEvent, matchers)
   145		}
   146	
   147		if count == 0 && !force {
   148			return 0, nil
   149		}
   150		return count, writeHookFile(path, rawHooks)
   151	}
   152	
   153	func (a *Agent) UninstallHooks() error {
   154		repoRoot := protocol.RepoRoot()
   155		path := hooksFilePath(repoRoot)
   156		if _, err := os.Stat(path); errors.Is(err, os.ErrNotExist) {
   157			return nil
   158		}
   159		rawHooks, err := readHookFile(path)
   160		if err != nil {
   161			return err
   162		}
   163		removeEntireHooks(rawHooks)
   164		return writeHookFile(path, rawHooks)
   165	}
   166	
   167	func (a *Agent) AreHooksInstalled() bool {
   168		repoRoot := protocol.RepoRoot()
   169		rawHooks, err := readHookFile(hooksFilePath(repoRoot))
   170		if err != nil {
   171			return false
   172		}
   173		for _, spec := range hookSpecs {
   174			var matchers []grokHookMatcher
   175			parseHookType(rawHooks, spec.GrokEvent, &matchers)
   176			if !hookExists(matchers, spec.Matcher, spec.EntryName) {
   177				return false
   178			}
   179		}
   180		return true
   181	}
   182	
   183	func parseHookInput(input []byte) (grokHookInputRaw, error) {
   184		var raw grokHookInputRaw
   185		input = bytes.TrimSpace(input)
   186		if len(input) == 0 {
   187			return raw, nil
   188		}
   189		if err := json.Unmarshal(input, &raw); err != nil {
   190			return raw, fmt.Errorf("parse grok hook input: %w", err)
   191		}
   192		return raw, nil
   193	}
   194	
   195	func normalizeRawHook(raw *grokHookInputRaw, hookName string) {
   196		if strings.TrimSpace(raw.SessionID) == "" {
   197			raw.SessionID = strings.TrimSpace(raw.SessionIDCamel)
   198		}
   199		if strings.TrimSpace(raw.SessionID) == "" {
   200			raw.SessionID = stubSessionID
   201		}
   202		if strings.TrimSpace(raw.Timestamp) == "" {
   203			raw.Timestamp = time.Now().UTC().Format(time.RFC3339)
   204		}
   205		if strings.TrimSpace(raw.CWD) == "" {
   206			raw.CWD = raw.WorkspaceRoot
   207		}
   208		if strings.TrimSpace(raw.Prompt) == "" {
   209			raw.Prompt = raw.UserPrompt
   210		}
   211		if strings.TrimSpace(raw.Model) == "" && raw.LLMRequest.Model != "" {
   212			raw.Model = raw.LLMRequest.Model
   213		}
   214		if len(bytes.TrimSpace(raw.ToolInput)) == 0 {
   215			raw.ToolInput = firstRawMessage(raw.Inputs, raw.Input)
   216		}
   217		if len(bytes.TrimSpace(raw.ToolResponse)) == 0 {
   218			raw.ToolResponse = firstRawMessage(raw.ToolResponse, raw.ToolResult, raw.Response)
   219		}
   220		if raw.ToolName == "" && (hookName == HookNamePostToolUse || hookName == HookNamePostToolUseFailure) {
   221			raw.ToolName = "unknown"
   222		}
   223	}
   224	
   225	func grokEventName(hookName string, existing string, existingCamel string) string {
   226		if strings.TrimSpace(existing) != "" {
   227			return existing
   228		}
   229		if strings.TrimSpace(existingCamel) != "" {
   230			return existingCamel
   231		}
   232		switch hookName {
   233		case HookNameSessionStart:
   234			return "SessionStart"
   235		case HookNameUserPromptSubmit:
   236			return "UserPromptSubmit"
   237		case HookNamePreToolUse:
   238			return "PreToolUse"
   239		case HookNameStop:
   240			return "Stop"

