  1	package grok
  2	
  3	import (
  4		"bytes"
  5		"encoding/base64"
  6		"encoding/json"
  7		"errors"
  8		"os"
  9		"path/filepath"
 10		"strings"
 11		"testing"
 12	
 13		"github.com/entireio/external-agents/agents/entire-agent-grok/internal/protocol"
 14	)
 15	
 16	// realTranscript mirrors the shape Grok 1.0.5 actually writes: a system line, a
 17	// <user_info> preamble, synthetic <system-reminder> injections carrying
 18	// synthetic_reason, real prompts tagged with prompt_index, reasoning lines with
 19	// an opaque encrypted_content, and tool results on their own lines.
 20	const realTranscript = `{"type":"system","content":"You are Grok."}
 21	{"type":"user","content":[{"type":"text","text":"<user_info>\nOS Version: macos\n</user_info>"}]}
 22	{"type":"user","synthetic_reason":"system_reminder","content":[{"type":"text","text":"<system-reminder>\nMCP server connected: pw\n</system-reminder>"}]}
 23	{"type":"user","prompt_index":0,"content":[{"type":"text","text":"<user_query>\nCreate hello.txt\n</user_query>"}]}
 24	{"type":"reasoning","id":"r1","model_id":"grok-4.6","summary":[{"type":"summary_text","text":"The user wants a file."}],"encrypted_content":"8k0KExCUBzdOBM4cHXfgVQ=="}
 25	{"type":"assistant","model_id":"grok-4.6","content":"","tool_calls":[{"id":"t1","name":"Write","arguments":"{\"path\":\"hello.txt\"}"}]}
 26	{"type":"tool_result","tool_call_id":"t1","content":"wrote hello.txt"}
 27	{"type":"assistant","model_id":"grok-4.6","content":"Created hello.txt"}
 28	`
 29	
 30	func compactLines(t *testing.T, data []byte) []compactLine {
 31		t.Helper()
 32		out, err := compactChatHistoryBytes(data)
 33		if err != nil {
 34			t.Fatalf("compactChatHistoryBytes: %v", err)
 35		}
 36		var lines []compactLine
 37		for _, raw := range strings.Split(strings.TrimSpace(string(out)), "\n") {
 38			if strings.TrimSpace(raw) == "" {
 39				continue
 40			}
 41			var line compactLine
 42			if err := json.Unmarshal([]byte(raw), &line); err != nil {
 43				t.Fatalf("unmarshal compact line %q: %v", raw, err)
 44			}
 45			lines = append(lines, line)
 46		}
 47		return lines
 48	}
 49	
 50	// Grok injects context as user-role messages. Only prompt_index-tagged lines are
 51	// things the human typed; treating the rest as prompts floods the summarizer.
 52	func TestCompactKeepsOnlyRealUserPrompts(t *testing.T) {
 53		var prompts []string
 54		for _, line := range compactLines(t, []byte(realTranscript)) {
 55			if line.Type != "user" {
 56				continue
 57			}
 58			blocks, ok := line.Content.([]any)
 59			if !ok || len(blocks) == 0 {
 60				t.Fatalf("unexpected user content: %#v", line.Content)
 61			}
 62			block, _ := blocks[0].(map[string]any)
 63			text, _ := block["text"].(string)
 64			prompts = append(prompts, text)
 65		}
 66		if len(prompts) != 1 {
 67			t.Fatalf("expected 1 real prompt, got %d: %q", len(prompts), prompts)
 68		}
 69		if prompts[0] != "Create hello.txt" {
 70			t.Fatalf("prompt not unwrapped from <user_query>: %q", prompts[0])
 71		}
 72	}
 73	
 74	// Grok writes tool output on a separate tool_result line keyed by tool_call_id.
 75	// Without joining them every tool call compacts with no result at all.
 76	func TestCompactAttachesToolResults(t *testing.T) {
 77		var found int
 78		for _, line := range compactLines(t, []byte(realTranscript)) {
 79			blocks, ok := line.Content.([]any)
 80			if !ok {
 81				continue
 82			}
 83			for _, raw := range blocks {
 84				block, _ := raw.(map[string]any)
 85				if block["type"] != "tool_use" {
 86					continue
 87				}
 88				found++
 89				result, ok := block["result"].(map[string]any)
 90				if !ok {
 91					t.Fatalf("tool_use %v has no result", block["id"])
 92				}
 93				if got := result["output"]; got != "wrote hello.txt" {
 94					t.Fatalf("unexpected tool output: %v", got)
 95				}
 96			}
 97		}
 98		if found != 1 {
 99			t.Fatalf("expected 1 tool_use block, got %d", found)
100		}
101	}
102	
103	// The reasoning summary is useful context; encrypted_content is opaque and is
104	// the field redaction corrupts, so it must never reach the compacted output.
105	func TestCompactKeepsReasoningSummaryButNotEncryptedContent(t *testing.T) {
106		out, err := compactChatHistoryBytes([]byte(realTranscript))
107		if err != nil {
108			t.Fatal(err)
109		}
110		if !strings.Contains(string(out), "The user wants a file.") {
111			t.Fatal("reasoning summary was dropped")
112		}
113		if strings.Contains(string(out), "encrypted_content") || strings.Contains(string(out), "8k0KExCUBzdOBM4cHXfgVQ==") {
114			t.Fatal("encrypted_content leaked into the compacted transcript")
115		}
116	}
117	
118	// Entire scopes a checkpoint by slicing from a mid-session offset and reads the
119	// file while Grok is still appending. Neither should fail the whole parse: an
120	// error here surfaces as "transcript has no content to summarize".
121	func TestCompactToleratesTruncatedLines(t *testing.T) {
122		full := []byte(realTranscript)
123		cases := map[string][]byte{
124			"slice starting mid-line": full[len(full)/2:],
125			"half-flushed final line": append(append([]byte{}, full...), []byte(`{"type":"assistant","cont`)...),
126		}
127		for name, data := range cases {
128			t.Run(name, func(t *testing.T) {
129				if _, err := compactChatHistoryBytes(data); err != nil {
130					t.Fatalf("expected tolerant parse, got %v", err)
131				}
132			})
133		}
134	}
135	
136	// A checkpoint slice can begin after the assistant line that issued a call,
137	// leaving its result orphaned. The output must still carry the tool output.
138	func TestCompactEmitsOrphanedToolResult(t *testing.T) {
139		orphan := []byte(`{"type":"tool_result","tool_call_id":"t1","content":"wrote hello.txt"}` + "\n")
140		out, err := compactChatHistoryBytes(orphan)
141		if err != nil {
142			t.Fatalf("orphaned tool_result should still compact: %v", err)
143		}
144		if !strings.Contains(string(out), "wrote hello.txt") {
145			t.Fatal("orphaned tool result output was lost")
146		}
